// Ảnh do Gemini NB2.1 vẽ và chữ do model viết, từ thông số kèo của bài E2E
// (ý tưởng + ngữ cảnh -> enhancer -> template phong cách -> ảnh 896x1200).
// Nhúng base64 vì máy test không đọc được file trên Mac, mà ảnh test thì
// không được vào asset của bản phát hành. Đây là mẫu cố định; khi backend
// có luồng tạo ảnh thẻ thì thay bằng ảnh do chính luồng đó sinh ra.

/// Một thẻ của bài E2E: chữ như backend sẽ gửi, ảnh JPEG base64.
class E2ECard {
  const E2ECard({
    required this.key,
    required this.tier,
    required this.styleName,
    required this.kind,
    required this.hero,
    required this.title,
    required this.desc,
    required this.owner,
    required this.serial,
    required this.meta,
    required this.date,
    required this.art,
  });

  final String key;
  final String tier;
  final String styleName;
  final String kind;
  final String hero;
  final String title;
  final String desc;
  final String owner;
  final String serial;
  final String meta;
  final String date;
  final String art;

  E2ECard withArt(String art) => E2ECard(
    key: key,
    tier: tier,
    styleName: styleName,
    kind: kind,
    hero: hero,
    title: title,
    desc: desc,
    owner: owner,
    serial: serial,
    meta: meta,
    date: date,
    art: art,
  );
}

